#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "`event` is one of `enrolled` or `revoked`, not the raw task name.",
                "{\n  \"at\": \"2026-09-25T02:10:31Z\",\n  \"by\": \"did:webvh:QmDanaScid8:acme-vtc.example:dana\",\n  \"credentialId\": \"c3RlcHVwLWNyZWQtY2Fyb2w\",\n  \"did\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\",\n  \"event\": \"enroll\"\n}",
            ),
            (
                "`by` is REQUIRED even when the member acted on their own credential — the recipient compares it to `did` to tell self-service from an administrator, and cannot if it is missing.",
                "{\n  \"at\": \"2026-09-25T02:10:31Z\",\n  \"credentialId\": \"c3RlcHVwLWNyZWQtY2Fyb2w\",\n  \"did\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\",\n  \"event\": \"revoked\"\n}",
            ),
            (
                "`credentialId` MUST NOT be empty — an empty id identifies nothing for the member to recognise.",
                "{\n  \"at\": \"2026-09-25T02:10:31Z\",\n  \"by\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\",\n  \"credentialId\": \"\",\n  \"did\": \"did:webvh:QmCarolScid3:acme-vtc.example:carol\",\n  \"event\": \"enrolled\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
